// ---------------------------------------------------------------------------
// The point of this workflow.
//
// A naive alert fires the moment one reading crosses a threshold, so a single
// blip pages someone at 3am and the alert is muted within a week. This holds a
// rolling window and fires only when the condition PERSISTS — 3 of the last 5
// readings — then refuses to fire again until the metric has actually recovered.
//
//   1. persistence  — a transient spike never alerts
//   2. idempotence  — an open alert is never duplicated
//   3. recovery     — the alert closes itself
//
// State lives in a file on disk, not in $getWorkflowStaticData(). Static data is
// only persisted for PRODUCTION executions, so a version built on it passes every
// manual test while being structurally incapable of ever reaching the threshold.
// A file works identically in manual and production runs, and is inspectable.
// ---------------------------------------------------------------------------
const THRESHOLD         = 200;
const WINDOW_SIZE       = 5;
const BREACHES_TO_ALERT = 3;

// --- load previous state (already parsed to json upstream) -----------------
let state = { window: [], alertOpen: false, issueNumber: null };

// 'Extract From File' nests parsed json under json.data by default, but returns
// it at the top level in some versions. Accept either rather than depend on it.
const raw  = $input.first()?.json ?? {};
const prev = Array.isArray(raw.window) ? raw
           : (raw.data && Array.isArray(raw.data.window) ? raw.data : null);

if (prev) {
  state = { window: prev.window, alertOpen: !!prev.alertOpen, issueNumber: prev.issueNumber ?? null };
}

// --- take the reading ------------------------------------------------------

const value = $('Fetch the metric').first().json.open_issues_count;
if (typeof value !== 'number') {
  throw new Error('Metric missing from payload — upstream API shape changed.');
}

state.window.push({ value, breached: value > THRESHOLD, at: new Date().toISOString() });
if (state.window.length > WINDOW_SIZE) state.window.shift();

const breaches        = state.window.filter((r) => r.breached).length;
const persistentlyBad = breaches >= BREACHES_TO_ALERT;
const fullyRecovered  = state.window.length === WINDOW_SIZE && breaches === 0;

// --- decide ----------------------------------------------------------------
let action = 'NOOP';
let reason = `${breaches}/${state.window.length} readings breached — no state change`;

if (persistentlyBad && !state.alertOpen) {
  action = 'OPEN_ALERT';
  reason = `${breaches} of the last ${state.window.length} readings breached ${THRESHOLD}`;
  state.alertOpen = true;
} else if (fullyRecovered && state.alertOpen) {
  action = 'CLOSE_ALERT';
  reason = `all ${WINDOW_SIZE} recent readings back under ${THRESHOLD}`;
  state.alertOpen = false;
} else if (persistentlyBad && state.alertOpen) {
  reason = 'already alerted — suppressed to avoid a duplicate ticket';
}

const out = {
  action,
  reason,
  value,
  threshold: THRESHOLD,
  breaches,
  window_size: state.window.length,
  alertOpen: state.alertOpen,
  issueNumber: state.issueNumber,
  window: state.window
};


return [{ json: out }];
